<?php require __DIR__.'/koneksi.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id_produk']??0);if($action==='clear'){unset($_SESSION['cart']);}elseif($action==='remove'){unset($_SESSION['cart'][$id]);}elseif(in_array($action,['add','update'],true)){$qty=max(0,(int)($_POST['jumlah']??1));$st=$koneksi->prepare('SELECT stok FROM produk WHERE id_produk=?');$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if($p){$qty=$action==='add'?($qty+($_SESSION['cart'][$id]??0)):$qty;$qty=min($qty,(int)$p['stok']);if($qty>0)$_SESSION['cart'][$id]=$qty;else unset($_SESSION['cart'][$id]);}}redirect('keranjang.php');}[$rows,$total]=cart_data($koneksi);$page_title='Keranjang Belanja';require __DIR__.'/partials/header.php';?><main class="container py-5"><h2 class="mb-4">Keranjang Belanja</h2><?php if(!$rows):?><div class="alert alert-info">Keranjang masih kosong. <a href="index.php">Belanja sekarang</a>.</div><?php else:?><div class="table-responsive"><table class="table bg-white"><thead><tr><th>Produk</th><th>Harga</th><th>Jumlah</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><?=e($p['nama_produk'])?></td><td><?=money($p['harga'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id_produk" value="<?=$p['id_produk']?>"><input type="number" class="form-control" style="width:85px" name="jumlah" min="0" max="<?=(int)$p['stok']?>" value="<?=$p['jumlah']?>"><button class="btn btn-sm btn-outline-secondary">Ubah</button></form></td><td><?=money($p['subtotal'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id_produk" value="<?=$p['id_produk']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div><h4 class="text-end">Total: <?=money($total)?></h4><div class="text-end"><a class="btn btn-pink" href="checkout.php">Checkout →</a></div><?php endif;?></main><?php require __DIR__.'/partials/footer.php';?>
